def dependency_layers(dependencies):
    nodes = set()
    for task, prereqs in dependencies.items():
        nodes.add(task)
        for prereq in prereqs:
            nodes.add(prereq)

    indegree = {node: 0 for node in nodes}
    successors = {node: set() for node in nodes}
    for task, prereqs in dependencies.items():
        for prereq in set(prereqs):
            if task not in successors[prereq]:
                successors[prereq].add(task)
                indegree[task] += 1

    remaining = set(nodes)
    layers = []
    while remaining:
        ready = sorted(node for node in remaining if indegree[node] == 0)
        if not ready:
            raise ValueError("dependency cycle detected")
        layers.append(ready)
        for node in ready:
            remaining.discard(node)
            for succ in successors[node]:
                indegree[succ] -= 1

    return layers
